insert into public.textos (id, conteudo) values
  (1, 'A saúde pública brasileira enfrenta o desafio de conciliar demandas crescentes com recursos limitados. Nos municípios, onde o cidadão de fato vive, as equipes de atenção básica tornam-se a porta de entrada do sistema. Contudo, não basta ampliar o número de unidades: é preciso qualificar o cuidado, fortalecer vínculos e garantir que a informação circule entre os serviços. Quando isso ocorre, evitam-se internações desnecessárias e o paciente é atendido no lugar certo, no tempo certo.'),
  (2, 'O trabalho em turnos é uma realidade para grande parte dos profissionais de enfermagem. Embora garanta a continuidade do cuidado, o plantão noturno altera o ritmo biológico e pode comprometer a qualidade do sono. Estudos indicam que trabalhadores privados de descanso cometem mais erros, sobretudo em tarefas que exigem atenção contínua, como o preparo de medicamentos. Por isso, especialistas recomendam que as instituições organizem escalas mais equilibradas e ofereçam espaços adequados para pausas. Cuidar de quem cuida, afinal, também é uma forma de proteger o paciente.'),
  (3, 'Durante décadas, o Brasil foi referência mundial em vacinação. Campanhas bem planejadas e a capilaridade das salas de vacina fizeram com que doenças como a poliomielite deixassem de circular no país. Nos últimos anos, porém, as coberturas vacinais caíram. Entre as causas apontadas estão a falsa sensação de segurança — já que muitos nunca viram essas doenças —, horários de atendimento pouco flexíveis e a circulação de notícias falsas. Reverter esse quadro exige informação de qualidade, mas também serviços que se adaptem à rotina da população.'),
  (4, 'A população brasileira envelhece em ritmo acelerado. Se em países europeus a transição demográfica levou mais de um século, aqui ela ocorre em poucas décadas. Essa velocidade impõe desafios ao sistema de saúde, que precisa lidar com o aumento das doenças crônicas e com a necessidade de cuidados prolongados. Mais do que acrescentar anos à vida, trata-se de acrescentar vida aos anos: garantir autonomia, participação social e dignidade a quem envelhece.'),
  (5, 'Acolher não é apenas receber bem. No cotidiano dos serviços, o acolhimento envolve escutar a queixa, reconhecer o que é prioridade e assumir a responsabilidade pela resposta, ainda que ela implique encaminhar o usuário a outro ponto da rede. Quando reduzido a uma triagem burocrática, perde seu sentido. Bem praticado, porém, transforma a relação entre profissionais e população, porque faz do serviço um lugar onde as pessoas se sentem ouvidas.'),
  (6, 'Saneamento básico é saúde. Cada real investido em água tratada e esgotamento sanitário reduz gastos com internações por doenças de veiculação hídrica, como diarreias e hepatite A. Apesar disso, milhões de brasileiros ainda vivem sem coleta de esgoto. O problema, que atinge principalmente as periferias urbanas e as áreas rurais, revela que as desigualdades sociais se expressam também no acesso a direitos básicos.'),
  (7, 'A sala de espera do posto abre antes do sol. Dona Lurdes chega com a pasta de exames presa ao peito, como quem carrega documentos de família; seu Antônio traz o rádio de pilha, que ninguém pediu, mas todos acabam ouvindo. Ali, o tempo é medido de outro modo: não pelos ponteiros do relógio na parede, sempre atrasado, mas pelos nomes chamados em voz alta. Cada nome é uma pequena vitória coletiva.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-001', 'pt', 1, 'De acordo com o texto, a principal ideia defendida é que:', '["a ampliação da atenção básica precisa vir acompanhada de qualificação do cuidado e de integração entre os serviços.","o número de unidades básicas no Brasil já é suficiente e não deve ser ampliado.","as internações hospitalares devem ser integralmente substituídas pela atenção básica.","os municípios dispõem de recursos ilimitados para a saúde pública.","a circulação de informação entre serviços é irrelevante quando há muitas unidades."]'::jsonb, 0, 'O autor afirma que "não basta ampliar": é preciso qualificar o cuidado, fortalecer vínculos e garantir a circulação da informação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-002', 'pt', 1, 'No trecho "Contudo, não basta ampliar o número de unidades", o conectivo "Contudo" pode ser substituído, sem alteração de sentido, por:', '["No entanto","Portanto","Porque","Assim que","Por conseguinte"]'::jsonb, 0, '"Contudo" é conjunção adversativa, equivalente a "no entanto", "todavia", "porém". "Portanto" e "por conseguinte" são conclusivas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-003', 'pt', 1, 'Em "Nos municípios, onde o cidadão de fato vive", o termo "onde" retoma:', '["municípios","cidadão","equipes","sistema","desafio"]'::jsonb, 0, '"Onde" é pronome relativo que indica lugar e retoma o antecedente "municípios".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-004', 'pt', 1, 'Em "evitam-se internações desnecessárias", o verbo está no plural porque:', '["concorda com o sujeito \"internações desnecessárias\", em construção de voz passiva sintética.","o sujeito é indeterminado, marcado pelo pronome \"se\".","concorda com o termo \"informação\", citado anteriormente.","trata-se de verbo impessoal, que sempre vai ao plural.","concorda com o termo \"serviços\", da oração anterior."]'::jsonb, 0, 'Verbo transitivo direto + "se" = voz passiva sintética: "internações desnecessárias são evitadas". O verbo concorda com o sujeito paciente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-005', 'pt', null, 'Assinale a frase em que o acento indicativo de crase está empregado corretamente:', '["O enfermeiro referiu-se à paciente do leito 4.","A equipe começou à trabalhar cedo.","Entregou o relatório à ela no fim do plantão.","O curativo será feito à partir das 8h.","Ficou frente à frente com o coordenador."]'::jsonb, 0, '"Referir-se a" + "a paciente" = à. Não há crase antes de verbo, de pronome pessoal (ela) nem em expressões com palavras repetidas (frente a frente); "a partir" também não tem crase.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-006', 'pt', null, 'Quanto à regência, de acordo com a norma-padrão, está correta a frase:', '["O técnico assistiu ao parto realizado no hospital.","Prefiro mais o plantão diurno do que o noturno.","Os pacientes obedecem o protocolo da unidade.","Esqueci do horário da medicação.","Ela namora com um enfermeiro do setor."]'::jsonb, 0, '"Assistir" no sentido de presenciar exige a preposição "a". Correções: prefiro X a Y; obedecem ao protocolo; esqueci o horário (ou esqueci-me do); namora um enfermeiro.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-007', 'pt', null, 'Assinale a alternativa corretamente pontuada:', '["Durante o plantão, os técnicos verificaram os sinais vitais de todos os pacientes.","Os técnicos de enfermagem, verificaram os sinais vitais.","O enfermeiro, entregou a escala ao coordenador.","A paciente que, chegou ontem recebeu alta.","Precisamos de: luvas máscaras e aventais."]'::jsonb, 0, 'A vírgula após adjunto adverbial deslocado é adequada. Não se separa sujeito do verbo por vírgula, e itens de enumeração devem ser separados por vírgula.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-008', 'pt', null, 'Quanto à colocação pronominal, segundo a norma-padrão, está correta a frase:', '["Não se deve administrar o medicamento sem prescrição.","Me entregue o prontuário, por favor.","Ninguém informou-me sobre a mudança de escala.","Quando avisaram-no, já era tarde.","Tinha esquecido-se do horário."]'::jsonb, 0, 'Palavras negativas (não, ninguém) e conjunções subordinativas (quando) atraem o pronome (próclise). Não se inicia frase com pronome oblíquo e não se usa ênclise ao particípio.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-009', 'pt', null, 'A palavra "saúde" é acentuada pela mesma regra que justifica o acento em:', '["juízo","médico","também","útil","pé"]'::jsonb, 0, 'Em "saúde" e "juízo", acentua-se o "i" ou "u" tônico que forma hiato com a vogal anterior. Médico = proparoxítona; também = oxítona em -em; útil = paroxítona em -l; pé = monossílabo tônico em -e.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-010', 'pt', 1, 'No texto, a palavra "conciliar" ("conciliar demandas crescentes com recursos limitados") tem sentido equivalente a:', '["harmonizar","separar","reduzir","ignorar","multiplicar"]'::jsonb, 0, 'Conciliar = pôr em acordo, harmonizar, compatibilizar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-011', 'pt', 2, 'A ideia central do texto é que:', '["garantir o descanso dos profissionais de enfermagem é também uma medida de segurança para o paciente.","o plantão noturno deve ser extinto nas instituições de saúde.","os erros de medicação decorrem exclusivamente da falta de conhecimento técnico.","o trabalho em turnos não interfere no ritmo biológico.","as pausas durante o plantão prejudicam a continuidade do cuidado."]'::jsonb, 0, 'O texto relaciona privação de sono a erros e conclui que "cuidar de quem cuida" protege o paciente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-012', 'pt', 2, 'No trecho "Embora garanta a continuidade do cuidado", a conjunção "Embora" estabelece relação de:', '["concessão.","causa.","finalidade.","conclusão.","proporção."]'::jsonb, 0, '"Embora" é conjunção concessiva, equivalente a "ainda que", "mesmo que".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-013', 'pt', 2, 'A palavra "sobretudo", em "sobretudo em tarefas que exigem atenção contínua", pode ser substituída, sem alteração de sentido, por:', '["principalmente.","raramente.","apenas.","contudo.","inclusive não."]'::jsonb, 0, '"Sobretudo" é advérbio que indica destaque: principalmente, especialmente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-014', 'pt', 2, 'No trecho "Por isso, especialistas recomendam...", a expressão "Por isso" introduz:', '["uma conclusão decorrente do que foi dito antes.","uma oposição ao que foi dito antes.","uma condição para o que foi dito antes.","um exemplo do que foi dito antes.","uma comparação com o que foi dito antes."]'::jsonb, 0, '"Por isso" retoma a informação anterior (mais erros por privação de sono) e introduz sua consequência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-015', 'pt', 2, 'Em "tarefas que exigem atenção contínua", o termo "que" retoma:', '["tarefas.","erros.","trabalhadores.","estudos.","medicamentos."]'::jsonb, 0, '"Que" é pronome relativo; quem "exige atenção contínua" são as tarefas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-016', 'pt', 3, 'Segundo o texto, NÃO é apontada como causa da queda das coberturas vacinais:', '["a falta de vacinas nos estoques.","a falsa sensação de segurança.","os horários de atendimento pouco flexíveis.","a circulação de notícias falsas.","o fato de muitos nunca terem visto essas doenças."]'::jsonb, 0, 'O texto cita sensação de segurança, horários pouco flexíveis e notícias falsas; não fala em desabastecimento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-017', 'pt', 3, 'No texto, os travessões em "— já que muitos nunca viram essas doenças —" foram empregados para:', '["isolar uma explicação inserida no período.","indicar a fala de um personagem.","marcar uma enumeração.","substituir os dois-pontos de uma citação.","indicar o fim do período."]'::jsonb, 0, 'Os travessões duplos isolam um comentário explicativo, como fariam vírgulas ou parênteses.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-018', 'pt', 3, 'No texto, a expressão "capilaridade das salas de vacina" refere-se:', '["à ampla distribuição das salas de vacina pelo território.","ao tamanho reduzido das salas de vacina.","à falta de salas de vacina no interior.","ao uso de agulhas finas na vacinação.","à concentração das salas de vacina nas capitais."]'::jsonb, 0, 'Em sentido figurado, capilaridade é a capacidade de alcançar pontos distantes, como os vasos capilares.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-019', 'pt', 3, 'Em "Nos últimos anos, porém, as coberturas vacinais caíram", o termo "porém" estabelece relação de:', '["oposição em relação à ideia de que o Brasil era referência em vacinação.","causa da queda das coberturas.","tempo em que a queda ocorreu.","conclusão sobre as campanhas.","adição de uma nova causa."]'::jsonb, 0, '"Porém" é conjunção adversativa: contrasta o passado de sucesso com a queda atual.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-020', 'pt', 3, 'No período "Reverter esse quadro exige informação de qualidade", o sujeito do verbo "exige" é:', '["a oração \"Reverter esse quadro\".","\"informação de qualidade\".","\"esse quadro\".","indeterminado.","inexistente (oração sem sujeito)."]'::jsonb, 0, 'O sujeito é oracional: "[Reverter esse quadro] exige...". "Informação de qualidade" é objeto direto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-021', 'pt', 4, 'No período "Se em países europeus a transição demográfica levou mais de um século, aqui ela ocorre em poucas décadas", o autor estabelece principalmente uma relação de:', '["contraste entre a velocidade do envelhecimento na Europa e no Brasil.","condição para que o Brasil envelheça.","finalidade do envelhecimento europeu.","consequência do envelhecimento europeu sobre o Brasil.","concordância entre as duas realidades."]'::jsonb, 0, 'Apesar do "se", não há condição real: a construção compara/contrasta os dois ritmos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-022', 'pt', 4, 'Em "Mais do que acrescentar anos à vida, trata-se de acrescentar vida aos anos", o autor:', '["inverte os termos para enfatizar que o foco deve ser a qualidade de vida na velhice.","defende que o principal objetivo é aumentar a expectativa de vida.","critica a autonomia da pessoa idosa.","afirma que os anos de vida não podem ser aumentados.","contradiz a ideia apresentada no início do texto."]'::jsonb, 0, 'A inversão (anos à vida / vida aos anos) destaca a qualidade, explicada após os dois-pontos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-023', 'pt', 4, 'No texto, os dois-pontos após "acrescentar vida aos anos" introduzem:', '["uma explicação do que significa \"acrescentar vida aos anos\".","uma fala direta.","uma ideia contrária à anterior.","uma pergunta retórica.","a conclusão de uma enumeração anterior."]'::jsonb, 0, 'Os dois-pontos anunciam o esclarecimento: autonomia, participação social e dignidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-024', 'pt', 4, 'Em "ao sistema de saúde, que precisa lidar com o aumento das doenças crônicas", o pronome "que" retoma:', '["sistema de saúde.","desafios.","velocidade.","doenças crônicas.","população brasileira."]'::jsonb, 0, 'Quem precisa lidar com as doenças crônicas é o sistema de saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-025', 'pt', 4, 'O acento grave em "acrescentar anos à vida" justifica-se porque:', '["o verbo \"acrescentar\" exige a preposição \"a\", que se funde ao artigo feminino \"a\" de \"vida\".","\"vida\" é palavra feminina, e toda palavra feminina recebe crase.","há uma locução adverbial de tempo.","se trata de uma expressão de modo.","o acento é facultativo e poderia ser retirado."]'::jsonb, 0, 'Acrescentar algo A alguma coisa + artigo "a" = à.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-026', 'pt', 5, 'De acordo com o texto, o acolhimento:', '["envolve escuta e responsabilização, e perde o sentido quando reduzido a uma triagem burocrática.","consiste apenas em receber bem o usuário na recepção.","dispensa o encaminhamento a outros pontos da rede.","é sinônimo de triagem administrativa.","deve ser feito exclusivamente pelo médico."]'::jsonb, 0, 'O texto define acolhimento como escutar, priorizar e assumir a resposta, criticando a triagem meramente burocrática.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-027', 'pt', 5, 'Em "ainda que ela implique encaminhar o usuário a outro ponto da rede", a expressão "ainda que" pode ser substituída, sem prejuízo de sentido, por:', '["mesmo que.","porque.","desde que.","para que.","à medida que."]'::jsonb, 0, '"Ainda que" e "mesmo que" são locuções concessivas. "Desde que" seria condicional.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-028', 'pt', 5, 'Em "Quando reduzido a uma triagem burocrática, perde seu sentido", o sujeito de "perde" é:', '["\"o acolhimento\", que está elíptico (subentendido).","\"uma triagem burocrática\".","\"seu sentido\".","indeterminado.","\"o usuário\"."]'::jsonb, 0, 'O sujeito oculto retoma "o acolhimento", termo do período anterior.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-029', 'pt', 5, 'No último período, a conjunção "porque" introduz:', '["a causa/explicação de o acolhimento transformar a relação entre profissionais e população.","uma condição para o acolhimento ocorrer.","uma finalidade do serviço de saúde.","uma oposição ao acolhimento.","uma consequência da triagem burocrática."]'::jsonb, 0, '"Porque" introduz a razão pela qual o acolhimento bem praticado transforma a relação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-030', 'pt', 5, 'Em "as pessoas se sentem ouvidas", o pronome "se":', '["integra o verbo pronominal \"sentir-se\".","é partícula apassivadora.","é índice de indeterminação do sujeito.","é conjunção condicional.","é conjunção integrante."]'::jsonb, 0, '"Sentir-se" (perceber-se em determinado estado) é verbo pronominal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-031', 'pt', 6, 'Em "Apesar disso, milhões de brasileiros ainda vivem sem coleta de esgoto", a expressão "Apesar disso" retoma:', '["a informação de que o investimento em saneamento reduz gastos com internações.","a falta de coleta de esgoto.","as periferias urbanas.","as desigualdades sociais.","a hepatite A."]'::jsonb, 0, '"Disso" retoma o benefício do saneamento; "apesar de" marca a concessão: mesmo com esse benefício, falta esgoto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-032', 'pt', 6, 'A oração "que atinge principalmente as periferias urbanas e as áreas rurais", por estar entre vírgulas, tem valor:', '["explicativo.","restritivo.","condicional.","temporal.","final."]'::jsonb, 0, 'Oração adjetiva entre vírgulas é explicativa: acrescenta uma informação sobre "o problema".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-033', 'pt', 6, 'No texto, "doenças de veiculação hídrica" são doenças:', '["transmitidas pela água.","transmitidas pelo ar.","causadas pelo excesso de chuvas.","hereditárias.","transmitidas por insetos."]'::jsonb, 0, 'Veiculação hídrica = transmissão pela água (exemplos do texto: diarreias e hepatite A).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-034', 'pt', 6, 'Infere-se do texto que o autor considera o saneamento básico:', '["um direito básico cuja ausência revela desigualdade social.","um gasto que não tem relação com a saúde.","um problema exclusivo das áreas rurais.","uma questão já resolvida no Brasil.","responsabilidade individual de cada morador."]'::jsonb, 0, 'O texto abre com "Saneamento básico é saúde" e fecha associando sua falta às desigualdades no acesso a direitos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-035', 'pt', 6, 'Em "milhões de brasileiros ainda vivem sem coleta de esgoto", o verbo está no plural porque concorda com:', '["\"milhões\", núcleo do sujeito.","\"brasileiros\", que é o objeto direto.","\"coleta\".","\"esgoto\".","o sujeito indeterminado."]'::jsonb, 0, 'O núcleo do sujeito é "milhões" (substantivo masculino plural).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-036', 'pt', null, 'Assinale a frase correta quanto à concordância verbal:', '["Fazia dois anos que ela trabalhava no hospital.","Fazem dois anos que ela trabalha no hospital.","Houveram muitos atendimentos no plantão.","Devem haver vagas para técnicos.","Existe muitas dúvidas sobre o protocolo."]'::jsonb, 0, '"Fazer" indicando tempo e "haver" (existir) são impessoais: ficam no singular, inclusive o auxiliar ("deve haver"). "Existir" concorda: existem muitas dúvidas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-037', 'pt', null, 'Assinale a frase correta quanto à concordância nominal:', '["As fichas seguem anexas ao prontuário.","Era meio-dia e meio quando a paciente chegou.","Havia bastante pacientes na fila.","Ela mesmo assinou o termo.","Hoje tivemos menas intercorrências."]'::jsonb, 0, '"Anexo" concorda com o substantivo. Correções: meio-dia e meia; bastantes pacientes; ela mesma; menos (invariável).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-038', 'pt', null, 'Assinale a frase correta quanto à regência verbal:', '["O atraso implicou prejuízo ao paciente.","Chegamos no hospital às 7h.","Ela aspira um cargo de coordenação.","O paciente simpatizou-se com a enfermeira.","Prefiro café do que chá."]'::jsonb, 0, '"Implicar" (acarretar) é transitivo direto. Correções: chegar a; aspirar a (desejar); simpatizar com (não pronominal); preferir algo a algo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-039', 'pt', null, 'O acento indicativo de crase está empregado corretamente em:', '["O plantão começa às 7 horas.","Fomos à pé até a unidade.","Ele se referiu à essa questão.","Volto daqui à pouco.","Entregou o comunicado à todos."]'::jsonb, 0, 'Há crase em horas determinadas. Não há crase antes de palavra masculina, de pronome demonstrativo "essa", de pronome indefinido ou na expressão "daqui a".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-040', 'pt', null, 'O uso do acento grave é FACULTATIVO em:', '["Entreguei o laudo à minha supervisora.","Cheguei à unidade às 7h.","Ele assistiu à reunião.","Dirigiu-se à recepção.","Fez referência à lei."]'::jsonb, 0, 'Antes de pronome possessivo feminino o artigo é opcional, logo a crase também.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-041', 'pt', null, 'Assinale a alternativa em que o emprego de "por que / porque / porquê / por quê" está correto:', '["Não sei por que ele faltou ao plantão.","Ele faltou por quê estava doente.","Porque você não veio ontem?","Explique o porque da decisão.","Você faltou porque?"]'::jsonb, 0, '"Por que" separado em pergunta direta/indireta; "porque" em resposta (causa); "porquê" substantivado; "por quê" em final de frase.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-042', 'pt', null, 'Assinale a alternativa em que todas as palavras estão grafadas corretamente:', '["exceção, análise, privilégio.","excessão, análise, privilégio.","exceção, análize, privilégio.","exceção, análise, previlégio.","excessão, análize, previlégio."]'::jsonb, 0, 'Grafias corretas: exceção (ç), análise (s), privilégio (pri-).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-043', 'pt', null, 'Assinale a alternativa em que todas as palavras estão grafadas corretamente:', '["paralisação, pesquisa, obsessão.","paralização, pesquisa, obsessão.","paralisação, pesquiza, obsessão.","paralisação, pesquisa, obcessão.","paralização, pesquiza, obcessão."]'::jsonb, 0, 'Paralisação deriva de paralisar (s); pesquisa (s); obsessão (bs + ss).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-044', 'pt', null, 'De acordo com o Novo Acordo Ortográfico, está correta a grafia de:', '["micro-ondas, anti-inflamatório, autoestima.","microondas, antiinflamatório, auto-estima.","micro-ondas, antiinflamatório, auto-estima.","microondas, anti-inflamatório, autoestima.","micro-ondas, anti-inflamatório, auto-estima."]'::jsonb, 0, 'Usa-se hífen quando o prefixo termina na mesma vogal que inicia o segundo elemento (micro-ondas, anti-inflamatório); prefixo terminado em vogal diferente se junta (autoestima).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-045', 'pt', null, 'De acordo com o Novo Acordo Ortográfico, estão corretamente grafadas:', '["ideia, heroico, voo.","idéia, heróico, vôo.","ideia, heróico, vôo.","idéia, heroico, voo.","ideia, heroico, vôo."]'::jsonb, 0, 'Caiu o acento dos ditongos abertos ei/oi em paroxítonas e do hiato oo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-046', 'pt', null, 'Em "A paciente chegou muito cansada", a palavra "muito" é classificada como:', '["advérbio.","adjetivo.","pronome indefinido.","substantivo.","conjunção."]'::jsonb, 0, '"Muito" intensifica o adjetivo "cansada": é advérbio de intensidade (invariável).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-047', 'pt', null, 'Assinale a oração sem sujeito:', '["Choveu muito durante a madrugada.","Os pacientes chegaram cedo.","Precisa-se de técnicos de enfermagem.","Disseram que haverá mudança na escala.","Saímos tarde do plantão."]'::jsonb, 0, 'Verbos que indicam fenômenos da natureza são impessoais. "Precisa-se" e "Disseram" têm sujeito indeterminado; "Saímos", sujeito oculto (nós).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-048', 'pt', null, 'A transposição correta de "A enfermeira aplicou a vacina" para a voz passiva analítica é:', '["A vacina foi aplicada pela enfermeira.","A vacina aplicou-se pela enfermeira.","Aplicou-se a vacina.","A vacina era aplicada pela enfermeira.","A enfermeira foi aplicada pela vacina."]'::jsonb, 0, 'Voz passiva analítica: ser + particípio, mantendo o tempo verbal (pretérito perfeito: foi aplicada).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-049', 'pt', null, 'Assinale a frase correta quanto à flexão verbal:', '["Quando você vir a enfermeira, entregue o recado.","Quando você ver a enfermeira, entregue o recado.","Se o gestor intervir, o problema será resolvido.","Se eu propor uma mudança, você aceita?","Quando ele repor o estoque, avise."]'::jsonb, 0, 'Futuro do subjuntivo: ver → vir; intervir → intervier; propor → propuser; repor → repuser.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-050', 'pt', null, '"Vacina e soro são imunobiológicos: ______ confere imunidade passiva; ______, imunidade ativa." Completam corretamente as lacunas:', '["este / aquela","esta / aquele","aquela / este","esse / essa","aquele / esta"]'::jsonb, 0, '"Este" retoma o termo mais próximo (o soro, imunidade passiva) e "aquela" o mais distante (a vacina, imunidade ativa).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-051', 'pt', null, 'De acordo com a norma-padrão, assinale a frase correta:', '["Esta é a reunião em que discutimos a escala.","Esta é a reunião onde discutimos a escala.","O paciente cujo o prontuário sumiu foi transferido.","Este é o setor que eu trabalho.","A técnica que eu falei chegou."]'::jsonb, 0, '"Onde" só indica lugar físico. Correções: cujo prontuário (sem artigo); setor em que trabalho; técnica de quem (de que) falei.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-052', 'pt', null, 'Na frase "A coordenação ratificou a informação", o verbo "ratificou" significa:', '["confirmou.","corrigiu.","anulou.","questionou.","divulgou."]'::jsonb, 0, 'Ratificar = confirmar; retificar = corrigir (parônimos).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-053', 'pt', null, 'Assinale a frase em que o parônimo está empregado corretamente:', '["O paciente agitado corre risco iminente de queda.","O cirurgião eminente de queda foi afastado.","A enfermeira fez uma descrição do sigilo profissional, guardando segredo.","O médico vai deferir o diagnóstico em outro paciente.","O tráfego de drogas é crime."]'::jsonb, 0, 'Iminente = prestes a acontecer; eminente = ilustre. Discrição = reserva; deferir = conceder; tráfico = comércio ilegal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-054', 'pt', null, 'Em "Como estava chovendo muito, o atendimento atrasou", a oração destacada "Como estava chovendo muito" expressa:', '["causa.","comparação.","conformidade.","concessão.","finalidade."]'::jsonb, 0, '"Como" anteposto à principal, com sentido de "porque", é conjunção causal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-055', 'pt', null, 'Em "Estude com antecedência, pois a prova está próxima", a conjunção "pois" é:', '["explicativa.","conclusiva.","adversativa.","alternativa.","aditiva."]'::jsonb, 0, '"Pois" antes do verbo, após oração imperativa, introduz explicação. Seria conclusivo se posposto ao verbo ("está, pois, próxima").') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-056', 'pt', null, 'Assinale a alternativa em que o plural de todas as palavras está correto:', '["cidadãos, capitães, pães.","cidadões, capitães, pães.","cidadãos, capitões, pães.","cidadãos, capitães, pãos.","cidadões, capitões, pãos."]'::jsonb, 0, 'Cidadão → cidadãos; capitão → capitães; pão → pães.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-057', 'pt', null, 'Assinale a frase correta quanto ao uso de "mal" e "mau":', '["O paciente passou mal durante a noite.","Ele é um mal profissional.","Foi um mau-entendido.","Mau chegou, já foi atendido.","Ela agiu de mau humor ontem e mau hoje."]'::jsonb, 0, '"Mal" é advérbio (oposto de bem) ou conjunção (assim que); "mau" é adjetivo (oposto de bom). Correto: mau profissional, mal-entendido, mal chegou.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-058', 'pt', null, 'Assinale a frase em que a expressão destacada está empregada corretamente:', '["Estudou todos os dias a fim de ser aprovada no concurso.","Estudou todos os dias afim de ser aprovada no concurso.","Somos profissionais de áreas a fim.","Ela não estava afim de trabalhar.","Fizeram tudo afim de evitar o erro."]'::jsonb, 0, '"A fim de" indica finalidade; "afim" significa semelhante, que tem afinidade (áreas afins).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-059', 'pt', null, 'Em "Ela lê Machado de Assis todos os dias", ocorre a figura de linguagem chamada:', '["metonímia, pois o autor é citado no lugar da obra.","metáfora.","hipérbole.","antítese.","eufemismo."]'::jsonb, 0, 'Metonímia: substituição de um termo por outro com o qual mantém relação de proximidade (autor pela obra).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-060', 'pt', null, 'Assinale a frase corretamente pontuada:', '["O médico prescreveu o medicamento, e a técnica o administrou.","O médico, prescreveu o medicamento e a técnica o administrou.","O médico prescreveu, o medicamento e a técnica o administrou.","O médico prescreveu o medicamento e a técnica, o administrou.","O médico prescreveu o medicamento e, a técnica o administrou."]'::jsonb, 0, 'Admite-se vírgula antes de "e" quando as orações coordenadas têm sujeitos diferentes. Não se separa sujeito de verbo nem verbo de complemento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-061', 'pt', 7, 'Considerando o texto como um todo, assinale a alternativa que expressa adequadamente o ponto de vista do autor sobre a sala de espera.', '["Embora reconheça a legitimidade das queixas sobre a demora, o autor destaca a sala de espera como espaço de convivência e solidariedade.","O autor considera a demora no atendimento irrelevante, já que a convivência compensa qualquer prejuízo aos usuários.","O autor critica a enfermeira, cujo cumprimento aos usuários atrasa o atendimento e aumenta a fila.","O texto defende que a fila seja extinta, por revelar a fragilidade da cidade.","O autor descreve a sala de espera exclusivamente como lugar de sofrimento e de conflito entre os usuários."]'::jsonb, 0, '"Há quem reclame da demora, e com razão" reconhece as queixas; o restante do texto destaca o encontro, a troca e a solidariedade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-062', 'pt', 7, 'No trecho "Dona Lurdes chega com a pasta de exames presa ao peito, como quem carrega documentos de família", a comparação estabelecida sugere que:', '["a personagem trata os exames com zelo, atribuindo-lhes grande valor.","os exames de Dona Lurdes pertencem, na verdade, a outros membros da família.","a personagem tem pressa em entregar os documentos à recepção.","os exames estão desorganizados e incompletos.","a pasta é pesada demais para ser carregada nas mãos."]'::jsonb, 0, 'A comparação ("como quem carrega documentos de família") atribui aos exames o valor e o cuidado de documentos preciosos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-063', 'pt', 7, 'Sobre o trecho "Troca-se receita de bolo, informação sobre o ônibus, notícia do vizinho que voltou do hospital", registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-064', 'pt', 7, 'No trecho "Contudo, quem observa com atenção percebe que a fila também é um lugar de encontro", o conectivo destacado pode ser substituído, sem prejuízo do sentido, por:', '["Todavia","Portanto","Porquanto","Conquanto","Logo"]'::jsonb, 0, '"Contudo" e "todavia" são adversativas. "Conquanto" é concessiva e exigiria reestruturação da frase; "portanto" e "logo" são conclusivas; "porquanto" é causal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-065', 'pt', 7, 'No período final, "é ali que a cidade se revela sem maquiagem: frágil, paciente e teimosamente solidária", predomina a figura de linguagem denominada:', '["personificação (prosopopeia), pois atribui à cidade características e ações humanas.","hipérbole, pois exagera intencionalmente o tamanho da fila.","eufemismo, pois suaviza a gravidade das doenças dos usuários.","antítese, pois opõe a palavra \"frágil\" à palavra \"paciente\".","onomatopeia, pois reproduz os sons da sala de espera."]'::jsonb, 0, 'A cidade "se revela sem maquiagem" e é "paciente" e "solidária": atributos humanos dados a um ser inanimado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-066', 'pt', 7, 'Em "teimosamente solidária", a palavra "teimosamente":', '["é advérbio formado por derivação sufixal e modifica o adjetivo \"solidária\".","é adjetivo que concorda com o substantivo \"cidade\".","é substantivo abstrato derivado do verbo teimar.","é advérbio de tempo que indica a duração da solidariedade.","é conjunção que liga \"paciente\" a \"solidária\"."]'::jsonb, 0, 'Teimoso + -mente = advérbio de modo/intensidade, modificando o adjetivo "solidária".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-067', 'pt', 7, 'Considerando os recursos linguísticos do texto, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-068', 'pt', 7, 'Quanto ao gênero e à tipologia, o texto se caracteriza como:', '["crônica, com trechos narrativos e descritivos a serviço de uma reflexão sobre o cotidiano.","notícia, cuja finalidade principal é informar objetivamente um fato recente.","texto instrucional, que orienta o leitor sobre como se comportar em uma fila.","editorial, que expressa a opinião institucional de um jornal sobre a gestão da saúde.","relatório técnico, com dados quantitativos sobre o tempo de espera."]'::jsonb, 0, 'Cena do cotidiano, linguagem expressiva e reflexão pessoal ao final são traços típicos da crônica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-069', 'pt', 8, 'O "paradoxo" a que o autor se refere no primeiro parágrafo consiste no fato de que:', '["o uso intenso dos antibióticos favorece a seleção de bactérias resistentes, reduzindo a eficácia desses medicamentos.","os antibióticos curam infecções simples, mas não tratam infecções graves.","as bactérias resistentes deixam de se multiplicar quando expostas aos antibióticos.","os antibióticos foram descobertos antes que se conhecessem as bactérias.","a medicina passou a depender exclusivamente dos antibióticos."]'::jsonb, 0, '"Quanto mais usamos esses medicamentos, menos eficazes eles se tornam": a pressão do uso seleciona variantes resistentes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-070', 'pt', 8, 'Assinale a alternativa em que o deslocamento do conectivo mantém a correção gramatical e o sentido de "Esse avanço, porém, trouxe consigo um paradoxo".', '["Porém, esse avanço trouxe consigo um paradoxo.","Esse avanço trouxe consigo, portanto, um paradoxo.","Esse avanço trouxe consigo um paradoxo, porque.","Esse avanço, porquanto, trouxe consigo um paradoxo.","Esse avanço trouxe consigo um paradoxo, conforme."]'::jsonb, 0, '"Porém" é adversativo e pode iniciar a oração ou aparecer intercalado. As demais trocam o sentido ou geram construções agramaticais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-071', 'pt', 8, 'No trecho "selecionam variantes resistentes, que se multiplicam e se espalham", o pronome "que" retoma:', '["variantes resistentes","as bactérias","uma pressão constante","esses medicamentos","um paradoxo"]'::jsonb, 0, 'São as variantes resistentes que se multiplicam e se espalham; a oração adjetiva explicativa (entre vírgula) se refere a elas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-072', 'pt', 8, 'Em "Estima-se que, se nada for feito, as infecções resistentes possam se tornar uma das principais causas de morte", a oração "se nada for feito" estabelece, em relação à oração em que se insere, valor de:', '["condição","causa","concessão","finalidade","proporção"]'::jsonb, 0, '"Se" é conjunção subordinativa condicional: a previsão depende da hipótese de nada ser feito.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-073', 'pt', 8, 'Acerca do período "Estima-se que, se nada for feito, as infecções resistentes possam se tornar uma das principais causas de morte nas próximas décadas", registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-074', 'pt', 8, 'De acordo com o texto, contribuem para a resistência bacteriana, EXCETO:', '["a vigilância e o investimento em pesquisa.","o uso indiscriminado de antibióticos em criações de animais.","a automedicação.","a interrupção precoce do tratamento.","a pressão constante exercida pelo uso dos medicamentos."]'::jsonb, 0, 'Vigilância e pesquisa aparecem no último parágrafo como formas de enfrentar o problema, não como causas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-075', 'pt', 8, 'No trecho "cada comprimido tomado sem necessidade é uma pequena aposta contra o futuro de todos", o autor:', '["emprega uma metáfora para enfatizar que o uso individual inadequado tem consequências coletivas.","utiliza linguagem denotativa para descrever uma prática comum em jogos de azar.","faz uma hipérbole para afirmar que todo comprimido é perigoso.","recorre à ironia para defender a automedicação.","emprega eufemismo para suavizar os riscos da resistência bacteriana."]'::jsonb, 0, '"Aposta contra o futuro" é metáfora: o ato individual compromete a eficácia futura dos antibióticos para toda a coletividade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-076', 'pt', 8, 'A grafia "micro-organismos", empregada no texto, está de acordo com o Acordo Ortográfico vigente porque:', '["usa-se hífen quando o prefixo termina com a mesma vogal que inicia o segundo elemento.","todo prefixo de origem grega exige hífen.","o hífen é obrigatório antes de qualquer palavra iniciada por vogal.","o segundo elemento é uma palavra paroxítona.","palavras compostas da área da saúde são sempre hifenizadas."]'::jsonb, 0, 'Prefixo terminado em vogal igual à inicial do segundo elemento: micro-organismo, micro-ondas, anti-inflamatório. Com vogais diferentes, junta-se: autoestima.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-077', 'pt', 8, 'O conectivo "Afinal", que inicia o último período do texto, introduz:', '["uma conclusão que reforça a argumentação desenvolvida.","uma ideia contrária à tese defendida.","uma condição para que a tese seja válida.","um exemplo isolado sem relação com o restante.","uma concessão ao ponto de vista dos opositores."]'::jsonb, 0, '"Afinal" tem valor conclusivo: arremata o raciocínio sobre responsabilidade coletiva.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-078', 'pt', 9, 'A principal ideia defendida no texto é a de que:', '["o calor extremo passou a ser um problema de saúde pública, que exige planejamento e adaptação das cidades.","as ondas de calor afetam apenas pessoas com doenças crônicas.","a exposição ao sol deve ser totalmente proibida durante o verão.","os serviços de emergência são os únicos responsáveis por enfrentar o calor extremo.","o calor é um desconforto passageiro, sem impacto relevante na saúde."]'::jsonb, 0, 'O último parágrafo sintetiza a tese: o calor "deixou de ser um desconforto passageiro e passou a ser um problema de saúde pública".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-079', 'pt', 9, 'Em "ao calor extremo, que pode provocar desidratação", o termo "que":', '["é pronome relativo e retoma \"calor extremo\".","é conjunção integrante e introduz oração substantiva.","é pronome relativo e retoma \"pessoas com doenças crônicas\".","é conjunção causal, equivalente a \"porque\".","é partícula expletiva, podendo ser retirada sem alteração."]'::jsonb, 0, 'É o calor extremo que pode provocar desidratação; o "que" introduz oração adjetiva explicativa.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-080', 'pt', 9, 'A locução verbal "têm batido", no primeiro período, indica:', '["ação que se repete ou se prolonga do passado até o momento presente.","ação concluída em um momento definido do passado.","ação que ainda vai ocorrer no futuro.","hipótese sobre um fato que pode não acontecer.","ordem dirigida aos leitores do texto."]'::jsonb, 0, 'O pretérito perfeito composto (ter no presente + particípio) expressa ação repetida ou contínua até o presente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-081', 'pt', 9, 'Considerando o período "Mais áreas verdes, bebedouros em espaços públicos e horários de trabalho ajustados para quem trabalha exposto ao sol são algumas das medidas recomendadas", registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-082', 'pt', 9, 'Caso o trecho "evitar a exposição ao sol entre 10h e 16h" fosse reescrito indicando o período com as preposições "de" e "a", a forma correta, segundo a norma-padrão, seria:', '["evitar a exposição ao sol das 10h às 16h.","evitar a exposição ao sol das 10h as 16h.","evitar a exposição ao sol da 10h à 16h.","evitar a exposição ao sol de 10h às 16h.","evitar a exposição ao sol à partir das 10h até às 16h."]'::jsonb, 0, 'Com horas determinadas, usa-se "das... às..." (preposição + artigo). "De 10h a 16h" (sem artigos) também seria possível; misturar "de" com "às" não é.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-083', 'pt', 9, 'Em "o calor deixou de ser um desconforto passageiro e passou a ser um problema de saúde pública", as locuções verbais destacam:', '["a mudança na forma como o calor é compreendido, com o fim de um estado e o início de outro.","a repetição de uma ação habitual.","uma ordem dada aos pesquisadores.","uma hipótese que o autor rejeita.","uma comparação de igualdade entre o calor e as epidemias."]'::jsonb, 0, '"Deixar de" marca o término; "passar a" marca o início de um novo estado (valor aspectual).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-084', 'pt', 9, 'A expressão "tanto quanto", no último período, estabelece relação de:', '["comparação de igualdade.","causa e consequência.","oposição.","condição.","finalidade."]'::jsonb, 0, 'O calor exige planejamento na mesma medida que as epidemias tradicionais: comparação de igualdade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-085', 'pt', 9, 'Considerando a finalidade e a linguagem, o texto é predominantemente:', '["expositivo-informativo, de caráter jornalístico, com apoio na fala de especialistas.","narrativo, centrado na história de um personagem.","poético, com predomínio da função emotiva.","injuntivo, como um manual de instruções.","argumentativo de cunho publicitário, com o objetivo de vender um produto."]'::jsonb, 0, 'O texto informa sobre um fenômeno e seus efeitos, recorrendo a especialistas e pesquisadores, como em uma reportagem.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-086', 'pt', 10, 'De acordo com o texto, é correto afirmar que:', '["as ferramentas estruturadas ajudam a comunicação, mas a segurança depende também da escuta e da compreensão das informações.","as ferramentas de comunicação eliminam completamente os erros na passagem de plantão.","a passagem de plantão deve ser feita apenas por escrito, para evitar ambiguidades.","a responsabilidade pela comunicação é exclusiva de quem sai do plantão.","perguntas durante a passagem de plantão devem ser evitadas, pois atrasam o turno."]'::jsonb, 0, '"Nenhuma ferramenta, contudo, substitui a escuta atenta"; comunicação segura é garantir a compreensão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-087', 'pt', 10, 'No trecho "Nesse intervalo curto, informações essenciais podem se perder, e é justamente aí que muitos erros têm origem", o advérbio "aí" retoma:', '["o intervalo curto da passagem de plantão.","as instituições de saúde.","as ferramentas de comunicação.","o próximo turno.","a recomendação do profissional."]'::jsonb, 0, '"Aí" tem valor anafórico e remete a "nesse intervalo curto".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-088', 'pt', 10, 'Na forma verbal "vêm adotando", o acento gráfico em "vêm" justifica-se por:', '["marcar a 3ª pessoa do plural do verbo vir, distinguindo-a do singular \"vem\".","ser palavra oxítona terminada em -em.","ser monossílabo tônico terminado em -e.","indicar a crase da preposição com o artigo.","marcar um hiato."]'::jsonb, 0, 'Acento diferencial de número: ele vem / eles vêm (o mesmo ocorre com ter: tem / têm).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-089', 'pt', 10, 'As aspas empregadas em "quando todos falam a mesma ''língua''" indicam que a palavra foi usada:', '["em sentido figurado, referindo-se a um padrão comum de comunicação.","como citação literal de um documento oficial.","para indicar um estrangeirismo.","com sentido irônico, desqualificando as ferramentas.","para marcar um erro gramatical intencional."]'::jsonb, 0, 'Não se trata de idioma, mas de um modo padronizado de comunicar: sentido conotativo destacado pelas aspas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-090', 'pt', 10, 'Considerando os aspectos linguísticos do terceiro parágrafo, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-091', 'pt', 10, 'No período "Quem sai precisa contar, em poucos minutos, o que aconteceu ao longo de horas", as vírgulas foram empregadas para:', '["isolar um adjunto adverbial intercalado.","separar o sujeito do verbo.","isolar um vocativo.","separar orações coordenadas assindéticas.","marcar a omissão de um verbo."]'::jsonb, 0, '"Em poucos minutos" é adjunto adverbial de tempo intercalado entre o verbo e o complemento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-092', 'pt', 10, 'A estrutura de comunicação descrita no segundo parágrafo, organizada em situação, antecedentes, avaliação e recomendação, é apresentada no texto como:', '["uma ferramenta que reduz ambiguidades ao padronizar o relato.","uma prática que dispensa a participação de quem chega ao plantão.","um método que substitui a escuta atenta.","uma exigência legal para todos os serviços de saúde.","um recurso usado apenas em situações de emergência."]'::jsonb, 0, '"A lógica é simples: quando todos falam a mesma ''língua'', diminui o espaço para ambiguidades."') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-093', 'pt', 11, 'A postura do narrador em relação ao saber popular sobre plantas medicinais pode ser descrita como:', '["respeitosa e crítica: reconhece seu valor afetivo e cultural, mas está atenta aos riscos.","de total rejeição, por considerar os chás perigosos.","de adesão incondicional, por acreditar que natural não faz mal.","indiferente, pois não vê relação entre os chás e o cuidado.","irônica, pois ridiculariza os costumes da avó."]'::jsonb, 0, 'O narrador afirma que nem todo remédio caseiro é inofensivo, mas "não consigo desprezar aquele saber" e começa o atendimento pelo diálogo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-094', 'pt', 11, 'Em "para a ansiedade, que ela chamava de ''nervoso'', erva-cidreira", a oração destacada entre vírgulas é classificada como:', '["subordinada adjetiva explicativa.","subordinada adjetiva restritiva.","subordinada substantiva objetiva direta.","subordinada adverbial causal.","coordenada sindética explicativa."]'::jsonb, 0, 'Introduzida por pronome relativo e isolada por vírgulas, acrescenta informação sobre "ansiedade": adjetiva explicativa.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-095', 'pt', 11, 'No primeiro parágrafo, o ponto e vírgula em "Para o estômago, boldo; para a tosse, guaco com mel; ..." foi empregado para:', '["separar itens de uma enumeração que já contêm vírgulas internas.","indicar uma pausa menor que a vírgula.","introduzir uma citação.","marcar o fim do parágrafo.","substituir a conjunção \"porque\"."]'::jsonb, 0, 'Cada item já tem vírgula (marcando a elipse do verbo "tinha"); o ponto e vírgula organiza a enumeração.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-096', 'pt', 11, 'A expressão "Ainda assim", no segundo parágrafo, introduz uma ideia de:', '["concessão, pois o narrador valoriza o saber da avó apesar dos riscos mencionados.","conclusão, pois confirma que os chás são inofensivos.","causa, pois explica por que as plantas são tóxicas.","tempo, pois indica quando o narrador estudou.","condição, pois o narrador só valoriza o saber se ele for científico."]'::jsonb, 0, '"Ainda assim" = "mesmo assim", "apesar disso": valor concessivo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-097', 'pt', 11, 'Sobre os recursos linguísticos do texto, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-098', 'pt', 11, 'Quanto à organização do texto, é correto afirmar que ele:', '["é narrado em primeira pessoa e combina relato de memórias com reflexão sobre a prática do cuidado.","é narrado em terceira pessoa por um observador que não participa dos fatos.","é um texto instrucional com etapas para o preparo de chás.","apresenta predominantemente dados estatísticos sobre plantas medicinais.","é um diálogo teatral entre a avó e o narrador."]'::jsonb, 0, 'Verbos e pronomes de 1ª pessoa ("minha avó", "cresci", "pergunto") e reflexão sobre o cuidado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-099', 'pt', 11, 'No trecho "As receitas não estavam escritas em lugar nenhum, mas passavam de geração em geração", a conjunção "mas" estabelece relação de:', '["oposição","adição","explicação","alternância","conclusão"]'::jsonb, 0, 'Contraste entre a ausência de registro escrito e a transmissão precisa entre gerações: valor adversativo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-100', 'pt', 11, 'Assinale a alternativa em que a palavra está grafada corretamente com hífen, assim como "erva-cidreira".', '["guarda-chuva","auto-estima","anti-inflamatorio","mal-criado","contra-regra"]'::jsonb, 0, 'Guarda-chuva (verbo + substantivo) mantém o hífen. Autoestima, anti-inflamatório (com acento), malcriado e contrarregra seguem o Acordo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-101', 'pt', 12, 'De acordo com o texto, o conceito de Saúde Única baseia-se na ideia de que:', '["a saúde humana está interligada à saúde dos animais e do ambiente.","as doenças infecciosas atingem exclusivamente os seres humanos.","a vacinação de animais dispensa o atendimento às pessoas.","somente médicos devem atuar na prevenção de doenças emergentes.","o desmatamento reduz o contato entre espécies."]'::jsonb, 0, '"A saúde humana não pode ser compreendida separadamente da saúde dos animais e do ambiente."') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-102', 'pt', 12, 'Em "uma ideia que cientistas defendiam havia décadas", o verbo "haver":', '["indica tempo decorrido, é impessoal e está corretamente flexionado no singular.","deveria estar no plural, concordando com \"décadas\".","tem o sentido de existir e concorda com \"cientistas\".","poderia ser substituído por \"a\" sem alteração de sentido.","é verbo auxiliar de \"defendiam\"."]'::jsonb, 0, 'Haver indicando tempo decorrido é impessoal ("havia décadas"); a forma "havia" combina com o imperfeito "defendiam".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-103', 'pt', 12, 'No segundo parágrafo, os travessões em "— médicos, enfermeiros, veterinários, biólogos, agrônomos —" foram empregados para:', '["isolar uma enumeração que especifica \"profissionais de diferentes áreas\".","indicar a fala de personagens.","marcar uma oposição entre os profissionais.","introduzir uma conclusão.","substituir parênteses em uma citação bibliográfica."]'::jsonb, 0, 'Os travessões duplos isolam um aposto enumerativo, que detalha quais são os profissionais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-104', 'pt', 12, 'Em "depende tanto da vacinação de cães e gatos quanto do atendimento rápido às pessoas mordidas", a estrutura "tanto... quanto" expressa relação de:', '["adição, ligando dois elementos igualmente necessários.","oposição entre a vacinação e o atendimento.","alternância, indicando que basta um dos elementos.","causa e efeito.","concessão."]'::jsonb, 0, 'Correlação aditiva: o controle depende de ambos os elementos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-105', 'pt', 12, 'Considerando aspectos de concordância e coesão do texto, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-106', 'pt', 12, 'A expressão "e mais barato", isolada por travessões no último período, tem a função de:', '["acrescentar um argumento que reforça a vantagem da prevenção.","contradizer a ideia de que prevenir é eficaz.","indicar a fonte da informação.","introduzir um exemplo sobre a raiva.","marcar a fala de um especialista."]'::jsonb, 0, 'O acréscimo destacado reforça o argumento a favor da prevenção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-107', 'pt', 12, 'O texto menciona como obstáculos à abordagem da Saúde Única:', '["a fragmentação dos serviços e a falta de sistemas de informação integrados.","o excesso de profissionais trabalhando de forma integrada.","a vacinação de cães e gatos.","a vigilância de aves migratórias.","o consenso de que prevenir é mais eficaz."]'::jsonb, 0, '"Ainda há obstáculos, como a fragmentação dos serviços e a falta de sistemas de informação integrados."') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-108', 'pt', null, 'Assinale a alternativa em que o acento indicativo de crase está empregado de acordo com a norma-padrão.', '["Refiro-me àquela proposta apresentada pela coordenação.","Na próxima semana, vou à Brasília para o congresso.","O técnico foi ao plantão à cavalo.","A equipe começou à organizar o setor.","Encaminhei o relatório à Vossa Senhoria."]'::jsonb, 0, 'Preposição "a" (referir-se a) + pronome "aquela" = àquela. Não há crase antes de nome de cidade sem artigo, de palavra masculina, de verbo nem de pronome de tratamento como Vossa Senhoria.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-109', 'pt', null, 'Sobre o emprego do acento grave indicativo de crase, registre V para as frases corretas e F para as incorretas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-110', 'pt', null, 'Assinale a alternativa em que o acento grave foi empregado INCORRETAMENTE.', '["Ficaram cara à cara com o problema.","O plantão começa às 19h.","Os profissionais devem obedecer às normas da instituição.","Serviram bife à milanesa no refeitório.","A diretora saiu à francesa da reunião."]'::jsonb, 0, 'Não há crase em expressões formadas por palavras repetidas (cara a cara, gota a gota). "À milanesa" e "à francesa" equivalem a "à moda".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-111', 'pt', null, 'O uso do acento indicativo de crase é facultativo em:', '["O paciente caminhou até a porta sem ajuda.","Os pacientes chegaram às sete horas.","A técnica dirigiu-se à recepção.","O relatório foi entregue à diretora.","Fez alusão à norma vigente."]'::jsonb, 0, 'Depois de "até", a preposição "a" é opcional; por isso, "até a porta" ou "até à porta" estão corretos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-112', 'pt', null, 'Assinale a alternativa correta quanto ao emprego da crase com pronomes relativos.', '["Esta é a norma à qual me referi na reunião.","Esta é a norma a qual me referi na reunião.","Este é o protocolo à que me referi.","Esta é a norma à que se submetem todos os servidores, segundo a qual.","Esta é a norma à cuja leitura todos têm acesso."]'::jsonb, 0, '"Referir-se a" + "a qual" = à qual. Não há crase antes de "que" sem artigo nem antes de "cuja".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-113', 'pt', null, 'Quanto à regência verbal, de acordo com a norma-padrão, registre V para as frases corretas e F para as incorretas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-114', 'pt', null, 'Assinale a alternativa correta quanto à regência verbal.', '["A decisão da gestão agradou aos funcionários.","O hospital pagou o fornecedor em dia.","Os pacientes preferem mais o atendimento matutino do que o noturno.","Ela se esqueceu o horário da medicação.","O plano implica em novas contratações."]'::jsonb, 0, 'Agradar (satisfazer) é transitivo indireto. Na norma-padrão: pagou ao fornecedor; preferem X a Y; esqueceu-se do horário (ou esqueceu o horário); implica novas contratações.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-115', 'pt', null, 'Assinale a alternativa correta quanto à regência nominal.', '["O ambulatório está situado na Rua das Flores.","A enfermeira é residente à Rua das Acácias.","É mais preferível prevenir do que remediar.","O paciente demonstrou ser apto com o trabalho.","O documento é acessível para com todos os servidores."]'::jsonb, 0, 'Situado e residente pedem a preposição "em". "Preferível" já contém a ideia de comparação: "É preferível prevenir a remediar". Apto a/para; acessível a.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-116', 'pt', null, 'Assinale a frase em que a regência do verbo está de acordo com a norma-padrão.', '["O diretor perdoou ao servidor o atraso.","Os alunos assistiram a aula de anatomia.","Lembrei do compromisso no último minuto.","A equipe chegou no hospital às 7h.","O médico informou-lhe de que o exame estava normal."]'::jsonb, 0, 'Perdoar: algo (OD) a alguém (OI). Assistir (presenciar) pede "a" → assistiram à aula; lembrei-me do compromisso; chegou ao hospital; informou-lhe que (ou informou-o de que).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-117', 'pt', null, 'Assinale a alternativa correta quanto à concordância verbal.', '["Deve fazer dois anos que o setor foi reformado.","Devem fazer dois anos que o setor foi reformado.","Haviam muitos pacientes na sala de espera.","Falta cinco dias para a prova.","Tratam-se de casos graves que exigem atenção."]'::jsonb, 0, 'Fazer (tempo decorrido) e haver (existir) são impessoais e transmitem a impessoalidade ao auxiliar. Faltar concorda com o sujeito (faltam cinco dias). "Trata-se de" fica no singular.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-118', 'pt', null, 'Sobre concordância verbal, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-119', 'pt', null, 'Assinale a alternativa correta quanto à concordância do verbo "ser" na indicação de horas.', '["Era meio-dia e meia quando a reunião terminou.","Eram meio-dia e meio quando a reunião terminou.","É dez horas, e o plantão já começou.","Já são uma hora da tarde.","Era duas horas quando o paciente chegou."]'::jsonb, 0, 'Na indicação de horas, o verbo "ser" concorda com o numeral: é uma hora, são dez horas, era meio-dia e meia (meia hora).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-120', 'pt', null, 'Com relação à concordância verbal com porcentagens e expressões partitivas, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-121', 'pt', null, 'Sobre concordância nominal, registre V para as frases corretas e F para as incorretas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-122', 'pt', null, 'Assinale a alternativa correta quanto à concordância nominal.', '["Após o pagamento, as servidoras ficaram quites com a associação.","Seguem anexo as declarações solicitadas.","As enfermeiras mesmo organizaram a escala.","Ela agradeceu: — Muito obrigado pela ajuda!","Os relatórios seguem inclusos aos processos, conforme os documentos anexo."]'::jsonb, 0, '"Quite" concorda com o sujeito (quites). Anexo, incluso, mesmo e obrigado são adjetivos e concordam: anexas, mesmas, obrigada, anexos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-123', 'pt', null, 'Compare: (1) "Os pacientes que estavam em jejum fizeram o exame." e (2) "Os pacientes, que estavam em jejum, fizeram o exame." É correto afirmar que:', '["em (1), apenas os pacientes em jejum fizeram o exame; em (2), todos os pacientes estavam em jejum e fizeram o exame.","as duas frases têm exatamente o mesmo sentido.","em (1), todos os pacientes fizeram o exame; em (2), apenas alguns.","a frase (2) está incorreta, pois não se usa vírgula antes de \"que\".","a frase (1) está incorreta, pois a oração adjetiva sempre exige vírgulas."]'::jsonb, 0, 'Sem vírgulas, a oração adjetiva é restritiva (limita o grupo); com vírgulas, é explicativa (generaliza a característica).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-124', 'pt', null, 'Assinale a alternativa corretamente pontuada.', '["Enfermeira, por favor, verifique os sinais vitais do paciente do leito 3.","Enfermeira por favor, verifique os sinais vitais do paciente do leito 3.","A enfermeira, verificou os sinais vitais do paciente do leito 3.","A enfermeira verificou, os sinais vitais do paciente do leito 3.","A enfermeira verificou os sinais vitais, do paciente do leito 3."]'::jsonb, 0, 'O vocativo ("Enfermeira") e a expressão intercalada ("por favor") são isolados por vírgulas. Não se separa sujeito de verbo nem verbo de complemento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-125', 'pt', null, 'Em "Eu fiquei com o turno da manhã; ela, com o da tarde", a vírgula após "ela" indica:', '["a omissão do verbo \"ficou\" (zeugma).","a presença de um vocativo.","a separação entre sujeito e predicado, obrigatória na norma-padrão.","a intercalação de um adjunto adverbial.","o início de uma oração subordinada."]'::jsonb, 0, 'A vírgula marca a elipse de um termo já expresso (zeugma): "ela [ficou] com o da tarde".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-126', 'pt', null, 'Sobre o emprego dos sinais de pontuação, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-127', 'pt', null, 'Assinale a alternativa correta quanto à colocação pronominal, segundo a norma-padrão.', '["Far-se-á a revisão dos protocolos no próximo mês.","Se fará a revisão dos protocolos no próximo mês.","Fará-se a revisão dos protocolos no próximo mês.","Ninguém avisou-me sobre a reunião.","Me disseram que a reunião foi cancelada."]'::jsonb, 0, 'Com verbo no futuro do presente, sem palavra atrativa, usa-se a mesóclise (far-se-á). Não se inicia período com pronome oblíquo, e "ninguém" atrai o pronome (ninguém me avisou).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-128', 'pt', null, 'Quanto à colocação pronominal, registre V para as frases corretas e F para as incorretas, de acordo com a norma-padrão.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-129', 'pt', null, 'Assinale a alternativa em que a expressão destacada está empregada corretamente.', '["Estude todos os dias, senão você não alcançará a aprovação.","Se não você estudar, não alcançará a aprovação.","Aonde fica o setor de vacinas?","Daqui há dois dias, o resultado sairá.","A decisão veio de encontro aos interesses dos usuários, que ficaram satisfeitos."]'::jsonb, 0, '"Senão" = caso contrário. "Onde" indica lugar em que algo está ("Onde fica"); "aonde" acompanha verbos de movimento. Futuro: "daqui a dois dias". Se os usuários ficaram satisfeitos, a decisão veio "ao encontro" de seus interesses.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-130', 'pt', null, 'Assinale a alternativa em que as expressões estão empregadas corretamente.', '["Discutimos acerca dos novos protocolos; o setor foi reformado há cerca de dois anos.","Discutimos há cerca dos novos protocolos; o setor foi reformado acerca de dois anos.","Discutimos a cerca dos novos protocolos; o setor foi reformado à cerca de dois anos.","Discutimos acerca dos novos protocolos; o setor foi reformado a cerca de dois anos.","Discutimos há cerca dos novos protocolos; o setor foi reformado há cerca de dois anos."]'::jsonb, 0, '"Acerca de" = sobre, a respeito de. "Há cerca de" = faz aproximadamente (tempo passado). "A cerca de" = a aproximadamente (distância ou tempo futuro).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-131', 'pt', null, 'Assinale a alternativa em que todas as palavras estão grafadas corretamente.', '["ascensão, pretensão, excesso, exceção","ascenção, pretensão, excesso, exceção","ascensão, pretenção, exceço, exceção","assensão, pretensão, excesso, excessão","ascensão, pretensão, ecesso, exceção"]'::jsonb, 0, 'Grafias corretas: ascensão (sc + s), pretensão (s), excesso (xc + ss), exceção (xc + ç).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-132', 'pt', null, 'Assinale a alternativa em que a palavra destacada está corretamente empregada.', '["O servidor infringiu a norma de segurança.","O servidor infligiu a norma de segurança.","A cessão do conselho começou às 9h.","O comprimento do contrato é obrigatório para todos.","A seção de cinema foi cancelada por falta de público."]'::jsonb, 0, 'Infringir = transgredir; infligir = aplicar (pena). Sessão = reunião/espetáculo; cessão = ato de ceder; seção = divisão. Cumprimento = execução; comprimento = extensão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-133', 'pt', null, 'A palavra "farmácia" é acentuada pela mesma regra que justifica o acento em:', '["consultório","diagnóstico","saúde","você","fácil"]'::jsonb, 0, 'Farmácia e consultório são paroxítonas terminadas em ditongo crescente. Diagnóstico é proparoxítona; saúde, hiato; você, oxítona em -e; fácil, paroxítona em -l.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-134', 'pt', null, 'Assinale a alternativa que apresenta palavras acentuadas pela mesma regra que "clínica".', '["diagnóstico, médico, técnico","saída, juízo, baú","também, ninguém, alguém","fácil, útil, possível","café, você, pé"]'::jsonb, 0, 'Todas as proparoxítonas são acentuadas: clínica, diagnóstico, médico, técnico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-135', 'pt', null, 'De acordo com o Acordo Ortográfico vigente, assinale a frase correta quanto ao acento diferencial.', '["O enfermeiro pôde sair mais cedo ontem; hoje, ele pode sair no horário.","O enfermeiro pode sair mais cedo ontem; hoje, ele pôde sair no horário.","O ônibus pára em frente ao hospital.","É preciso por o curativo antes da visita.","Eles têm que pôr o uniforme, e ele têm de fazer o mesmo."]'::jsonb, 0, 'Mantêm-se os acentos diferenciais de pôde (passado) × pode (presente) e de pôr (verbo) × por (preposição). "Para" (verbo) perdeu o acento. "Ele tem" (singular) não leva acento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-136', 'pt', null, 'Assinale a alternativa em que todas as palavras estão corretamente acentuadas.', '["raiz, raízes, juiz, juízes","raíz, raízes, juíz, juízes","raiz, raizes, juiz, juizes","raíz, raizes, juiz, juízes","raiz, raízes, juíz, juizes"]'::jsonb, 0, 'Não se acentua o "i" tônico do hiato quando seguido de "z" na mesma sílaba (ra-iz, ju-iz); no plural, ra-í-zes e ju-í-zes são acentuados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-137', 'pt', null, 'Assinale a alternativa em que todas as palavras estão grafadas de acordo com o Acordo Ortográfico vigente.', '["pós-operatório, pré-natal, recém-nascido","pós operatório, prenatal, recém nascido","posoperatório, pré natal, recémnascido","pós-operatório, pre-natal, recem-nascido","pós operatório, pré-natal, recemnascido"]'::jsonb, 0, 'Os prefixos tônicos pós-, pré- e recém- exigem hífen.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-138', 'pt', null, 'Assinale a alternativa em que todas as palavras estão grafadas corretamente.', '["anti-higiênico, infraestrutura, semiárido","antihigiênico, infra-estrutura, semi-árido","anti-higiênico, infra-estrutura, semiárido","antihigiênico, infraestrutura, semi-árido","anti higiênico, infraestrutura, semi árido"]'::jsonb, 0, 'Usa-se hífen antes de "h" (anti-higiênico). Prefixo terminado em vogal diferente da vogal inicial do segundo elemento: junta-se (infraestrutura, semiárido).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-139', 'pt', null, 'Na frase "Se você vier amanhã, traga os exames", a palavra "se" é:', '["conjunção subordinativa condicional.","pronome reflexivo.","partícula apassivadora.","índice de indeterminação do sujeito.","conjunção integrante."]'::jsonb, 0, '"Se" introduz a condição para que a ação ocorra.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-140', 'pt', null, 'Em "O não do paciente ao procedimento foi registrado no prontuário", a palavra "não" pertence à classe dos:', '["substantivos, por ter sido substantivada pelo artigo.","advérbios de negação.","pronomes indefinidos.","adjetivos.","verbos."]'::jsonb, 0, 'Antecedida de artigo, a palavra passa a funcionar como substantivo (derivação imprópria).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-141', 'pt', null, 'Em "Mesmo cansada, a técnica permaneceu no plantão", a expressão destacada estabelece relação de:', '["concessão","causa","conformidade","finalidade","proporção"]'::jsonb, 0, '"Mesmo cansada" = "ainda que estivesse cansada": a circunstância não impede a ação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-142', 'pt', null, 'Na frase "Entregou a carta a ela", as duas ocorrências de "a" são, respectivamente:', '["artigo definido e preposição.","preposição e artigo definido.","pronome oblíquo e preposição.","artigo definido e pronome oblíquo.","preposição e preposição."]'::jsonb, 0, '"A carta": artigo que determina o substantivo. "A ela": preposição exigida pelo verbo entregar (entregar algo a alguém).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-143', 'pt', null, 'Assinale a alternativa em que a palavra destacada é advérbio.', '["Os pacientes estavam bastante preocupados.","Havia bastantes leitos vazios.","Os resultados foram bons.","Cada paciente recebeu um kit.","O primeiro atendimento foi rápido."]'::jsonb, 0, '"Bastante" modifica o adjetivo "preocupados": é advérbio de intensidade (invariável). Em "bastantes leitos", é adjetivo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-144', 'pt', null, 'Em "O paciente chegou cansado ao pronto-socorro", o termo "cansado" exerce a função de:', '["predicativo do sujeito, em predicado verbo-nominal.","adjunto adnominal de \"paciente\".","objeto direto.","adjunto adverbial de modo.","predicativo do objeto."]'::jsonb, 0, '"Cansado" atribui uma característica ao sujeito, e o verbo "chegar" é significativo: predicado verbo-nominal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-145', 'pt', null, 'Em "A equipe considerou o procedimento seguro", o termo "seguro" exerce a função de:', '["predicativo do objeto.","predicativo do sujeito.","adjunto adnominal.","objeto direto.","complemento nominal."]'::jsonb, 0, '"Seguro" qualifica o objeto direto ("o procedimento") por meio do verbo: predicativo do objeto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-146', 'pt', null, 'Em "A coleta de sangue foi realizada às 7h", o termo "de sangue" é:', '["complemento nominal, pois \"sangue\" é o alvo da ação expressa por \"coleta\".","adjunto adnominal, pois indica posse.","objeto indireto do verbo realizar.","agente da passiva.","adjunto adverbial de lugar."]'::jsonb, 0, '"Coleta" é substantivo de ação; "sangue" sofre a ação (coleta-se sangue): complemento nominal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-147', 'pt', null, 'Em "O curativo foi realizado pela técnica de enfermagem", o termo "pela técnica de enfermagem" é:', '["agente da passiva.","objeto indireto.","adjunto adverbial de modo.","complemento nominal.","sujeito."]'::jsonb, 0, 'Na voz passiva analítica, quem pratica a ação é o agente da passiva.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-148', 'pt', null, 'Assinale a alternativa em que o sujeito é indeterminado.', '["Precisa-se de técnicos de enfermagem no plantão noturno.","Choveu muito durante a madrugada.","Vendem-se equipamentos usados.","Chegamos cedo ao hospital.","Os pacientes aguardavam na recepção."]'::jsonb, 0, 'Verbo transitivo indireto + "se" = índice de indeterminação do sujeito. "Choveu": oração sem sujeito; "Vendem-se equipamentos": sujeito "equipamentos" (voz passiva); "Chegamos": sujeito oculto (nós).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-149', 'pt', null, 'Quanto à transitividade verbal, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-150', 'pt', null, 'Em "Estava tão cansada que dormiu na sala de descanso", a oração "que dormiu na sala de descanso" é classificada como subordinada adverbial:', '["consecutiva","causal","comparativa","final","concessiva"]'::jsonb, 0, 'A estrutura "tão... que" introduz a consequência do que se afirma na oração principal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-151', 'pt', null, 'Em "À medida que a fila diminuía, a equipe se tranquilizava", a oração destacada expressa:', '["proporção","conformidade","finalidade","concessão","condição"]'::jsonb, 0, '"À medida que" e "à proporção que" introduzem orações adverbiais proporcionais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-152', 'pt', null, 'Em "O curativo foi feito conforme o protocolo determina", a oração destacada é subordinada adverbial:', '["conformativa","comparativa","causal","temporal","consecutiva"]'::jsonb, 0, '"Conforme", "segundo" e "como" (= conforme) introduzem orações conformativas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-153', 'pt', null, 'Em "A enfermeira orientou a família para que o tratamento fosse seguido corretamente", a oração destacada exprime:', '["finalidade","causa","consequência","condição","tempo"]'::jsonb, 0, '"Para que" introduz oração adverbial final.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-154', 'pt', null, 'Em "Espero que o paciente melhore logo", a oração "que o paciente melhore logo" é:', '["subordinada substantiva objetiva direta.","subordinada substantiva subjetiva.","subordinada adjetiva restritiva.","subordinada adverbial final.","coordenada sindética explicativa."]'::jsonb, 0, 'A oração completa o sentido do verbo transitivo direto "esperar" (espero isso).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-155', 'pt', null, 'Em "O paciente estava em jejum; logo, pôde realizar o exame", a oração iniciada por "logo" é:', '["coordenada sindética conclusiva.","coordenada sindética explicativa.","subordinada adverbial temporal.","coordenada sindética adversativa.","subordinada adverbial causal."]'::jsonb, 0, '"Logo", "portanto" e "por conseguinte" introduzem conclusão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-156', 'pt', null, 'Assinale a alternativa em que a oração destacada exprime tempo.', '["Quando o médico chegou, o paciente já estava estabilizado.","Como estava chovendo, a visita foi adiada.","Embora estivesse cansada, ela concluiu o relatório.","Se houver vagas, o paciente será transferido.","Caso o exame seja alterado, a equipe será avisada."]'::jsonb, 0, '"Quando" introduz oração temporal. As demais exprimem causa, concessão e condição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-157', 'pt', null, 'A transposição da frase "Vendem-se medicamentos sem receita" para a voz passiva analítica é:', '["Medicamentos são vendidos sem receita.","Vende-se medicamentos sem receita.","Alguém vende medicamentos sem receita.","Medicamentos vendem sem receita.","Medicamentos foram vendidos sem receita por alguém."]'::jsonb, 0, 'Voz passiva sintética (verbo + se) → analítica (ser + particípio), mantendo o tempo verbal (presente: são vendidos).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-158', 'pt', null, 'Em "A técnica feriu-se com a agulha durante o descarte", o verbo está na voz:', '["reflexiva, pois o sujeito pratica e sofre a ação.","passiva sintética.","passiva analítica.","ativa, com sujeito indeterminado.","reflexiva recíproca."]'::jsonb, 0, 'O sujeito (a técnica) é agente e paciente da ação de ferir.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-159', 'pt', null, 'Assinale a alternativa em que há uniformidade de tratamento, segundo a norma-padrão.', '["Você, venha até a recepção e traga seus documentos.","Você, vem até a recepção e traz teus documentos.","Tu, venha até a recepção e traga teus documentos.","Você, vem até a recepção e traga seus documentos.","Tu, vem até a recepção e traga seus documentos."]'::jsonb, 0, '"Você" exige verbo e pronomes na 3ª pessoa: venha, traga, seus. Com "tu": vem, traz, teus.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-160', 'pt', null, 'Assinale a alternativa em que a forma verbal está de acordo com a norma-padrão.', '["O diretor interveio na discussão entre os servidores.","O diretor interviu na discussão entre os servidores.","Se o paciente propor um acordo, avise-me.","O servidor reaveu os documentos extraviados.","Quando você ver a enfermeira, entregue o recado."]'::jsonb, 0, 'Intervir conjuga-se como vir (interveio). Futuro do subjuntivo: propuser, vir. Reaver segue haver nas formas com "v": reouve.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-161', 'pt', null, 'Assinale a alternativa em que há correlação adequada entre os tempos verbais.', '["Se o paciente seguisse as orientações, teria melhorado mais rápido.","Se o paciente seguir as orientações, teria melhorado mais rápido.","Se o paciente seguisse as orientações, terá melhorado mais rápido.","Se o paciente segue as orientações, teria melhorado mais rápido.","Se o paciente seguiria as orientações, teria melhorado mais rápido."]'::jsonb, 0, 'Pretérito imperfeito do subjuntivo (seguisse) correlaciona-se com o futuro do pretérito (teria melhorado).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-162', 'pt', null, 'Na frase "O medicamento mostrou-se inócuo para aquele tipo de infecção", a palavra "inócuo" pode ser substituída, sem alteração de sentido, por:', '["ineficaz/sem efeito","perigoso","caro","indispensável","contagioso"]'::jsonb, 0, 'Inócuo = que não produz efeito (ou que não causa dano). No contexto, o medicamento não teve efeito sobre a infecção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-163', 'pt', null, 'O antônimo de "efêmero" é:', '["duradouro","passageiro","breve","fugaz","transitório"]'::jsonb, 0, 'Efêmero = de curta duração; o antônimo é duradouro, permanente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-164', 'pt', null, 'Assinale a alternativa em que o termo destacado foi empregado com sentido conotativo.', '["A notícia caiu como uma bomba na equipe.","A bomba de infusão foi programada para 21 mL/h.","O paciente caiu da cama durante a madrugada.","A enfermeira trocou o equipo da bomba.","A bomba d''água do hospital foi consertada."]'::jsonb, 0, '"Caiu como uma bomba" é expressão figurada: a notícia teve grande impacto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-165', 'pt', null, 'Na frase "Depois de uma longa doença, ele partiu desta para melhor", identifica-se a figura de linguagem denominada:', '["eufemismo","hipérbole","ironia","metonímia","pleonasmo"]'::jsonb, 0, 'Eufemismo: suaviza uma ideia desagradável (morrer).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-166', 'pt', null, 'Em "Naquele corredor reinava um silêncio ensurdecedor", ocorre:', '["paradoxo (oxímoro), pela união de ideias contraditórias em um mesmo termo.","hipérbole, por exagero na quantidade de pessoas.","catacrese, pelo uso de palavra por falta de termo próprio.","metonímia, pela troca do todo pela parte.","pleonasmo vicioso."]'::jsonb, 0, 'Silêncio que ensurdece: ideias contraditórias reunidas em uma mesma expressão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-167', 'pt', null, 'Assinale a alternativa em que ocorre hipérbole.', '["Já expliquei esse procedimento mil vezes.","O pé da mesa estava quebrado.","Ela é uma flor de pessoa.","Bebeu dois copos de água.","O hospital acordou cedo."]'::jsonb, 0, 'Hipérbole é o exagero intencional ("mil vezes").') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-168', 'pt', null, 'Em "O braço da cadeira e o pé da mesa precisavam de reparo", as expressões destacadas exemplificam:', '["catacrese","personificação","antítese","eufemismo","ironia"]'::jsonb, 0, 'Catacrese: metáfora já incorporada à língua, usada por falta de termo específico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-169', 'pt', null, 'Em "A técnica chegou cedo e foi direto ao setor de vacinas", o sujeito da segunda oração não está expresso. Esse recurso de coesão denomina-se:', '["elipse","substituição lexical","repetição","catáfora","hiperonímia"]'::jsonb, 0, 'Omite-se um termo facilmente recuperável pelo contexto (a técnica).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-170', 'pt', null, 'No período "O plano de contingência foi aprovado. Ademais, a equipe recebeu novos equipamentos", o conectivo "Ademais" expressa:', '["adição","oposição","conclusão","causa","condição"]'::jsonb, 0, '"Ademais" = além disso.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-171', 'pt', null, 'Em "Não obstante as dificuldades, a equipe cumpriu as metas", a expressão "Não obstante" pode ser substituída, sem alteração de sentido, por:', '["Apesar de","Por causa de","Em virtude de","A fim de","Graças a"]'::jsonb, 0, '"Não obstante" tem valor concessivo/adversativo: apesar das dificuldades.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-172', 'pt', null, 'No trecho "A equipe recebeu os novos protocolos. Esses documentos orientam o atendimento", o termo "Esses documentos" constitui um mecanismo de coesão:', '["referencial, por substituição lexical que retoma \"os novos protocolos\".","sequencial, por meio de conector adversativo.","por elipse do sujeito.","catafórico, pois antecipa uma informação.","por repetição literal do termo anterior."]'::jsonb, 0, 'Um termo equivalente (hiperônimo) retoma o referente já mencionado: coesão referencial anafórica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-173', 'pt', null, 'No cartaz de campanha "Vacine-se! Proteja quem você ama", predomina a função da linguagem:', '["conativa (apelativa)","referencial","metalinguística","fática","poética"]'::jsonb, 0, 'O foco está no receptor, com verbos no imperativo para convencê-lo a agir.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-174', 'pt', null, 'Um verbete de dicionário que explica o significado da palavra "saúde" exemplifica a função da linguagem:', '["metalinguística","emotiva","conativa","fática","poética"]'::jsonb, 0, 'Usa-se a língua para falar da própria língua (o código).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-175', 'pt', null, 'A bula de um medicamento, com orientações sobre posologia, cuidados de armazenamento e o que fazer em caso de esquecimento de uma dose, pertence predominantemente ao tipo textual:', '["injuntivo (instrucional)","narrativo","poético","dissertativo-argumentativo","dialogal"]'::jsonb, 0, 'Predominam orientações e instruções ao leitor, típicas do texto injuntivo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-176', 'pt', null, 'Na frase "Alô, você está me ouvindo?", predomina a função da linguagem:', '["fática, voltada para testar ou manter o canal de comunicação.","referencial, voltada para informar um fato.","emotiva, voltada para os sentimentos do emissor.","poética, voltada para a forma da mensagem.","metalinguística, voltada para o código."]'::jsonb, 0, 'A função fática se centra no canal: iniciar, manter ou verificar a comunicação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-177', 'pt', null, 'Considere o enunciado: "Os profissionais que participaram do treinamento, embora estivessem cansados, demonstraram grande interesse pelo tema." Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-178', 'pt', null, 'Considere o período "Muitos usuários não sabiam que a unidade oferecia testes rápidos, por isso a equipe intensificou a divulgação." Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('pt-179', 'pt', null, 'Leia a frase: "Havia muitas dúvidas sobre o novo protocolo, mas a capacitação esclareceu-as." Analise as afirmativas a seguir.
